	/**
	 * An interrupted load leaves a resumable workspace beside the store. The setup has to surface it and offer to
	 * continue before it asks how to configure a load, because every one of those answers is wasted when the answer to
	 * "what do you want to do" is "carry on with the run that is already half done".
	 */
	@Test
	void interactiveSetupOffersToResumeAnUnfinishedRunBeforeAnyOtherPrompt() throws Exception {
		Path store = temporaryDirectory.resolve("store");
		Path input = temporaryDirectory.resolve("input.nt");
		Files.writeString(input, "this line is not an N-Triples statement\n");

		int interrupted = LmdbBulkLoad.run(new String[] {
				"--store", store.toString(),
				"--input", input.toString(),
				"--progress", "none"
		}, new ByteArrayInputStream(new byte[0]), new PrintStream(new ByteArrayOutputStream()),
				new PrintStream(new ByteArrayOutputStream()));
		assertThat(interrupted).isEqualTo(1);
		assertThat(temporaryDirectory.resolve(".store.lmdb-bulk-load")).isDirectory();

		// Repairing the file the run choked on is the whole reason to come back, and the run knows which file that
		// was, so resuming reads it again without being told where it is.
		Files.writeString(input, "<urn:subject> <urn:predicate> <urn:object> .\n");
		String answers = String.join("\n", "y", "none") + "\n";
		ByteArrayOutputStream standardOutput = new ByteArrayOutputStream();
		ByteArrayOutputStream standardError = new ByteArrayOutputStream();

		int exitCode = LmdbBulkLoad.run(new String[] {
				"--interactive",
				"--store", store.toString()
		}, new ByteArrayInputStream(answers.getBytes(StandardCharsets.UTF_8)),
				new PrintStream(standardOutput), new PrintStream(standardError));

		String prompts = standardError.toString(StandardCharsets.UTF_8);
		assertThat(prompts)
				.as("the unfinished run is reported with the store it belongs to")
				.contains("unfinished LMDB bulk load")
				.contains(store.toString());
		assertThat(prompts.indexOf("Resume"))
				.as("resuming is offered before the setup asks anything else")
				.isGreaterThanOrEqualTo(0)
				.isLessThan(prompts.indexOf("Progress mode"));
		assertThat(prompts)
				.as("the files it will read again are named, not just counted")
				.contains(input.toString());
		assertThat(exitCode).as(prompts).isZero();
		assertThat(standardOutput.toString(StandardCharsets.UTF_8))
				.contains("parsed=1")
				.contains("stored=1");
	}

