	/**
	 * The interrupted run recorded everything it was running under, so resuming it asks nothing that the workspace
	 * already answers. What matters is not the shorter prompt list but the store that comes out: it carries the indexes
	 * and literal handling of the original run, which nobody retyped.
	 */
	@Test
	void interactiveSetupResumesWithTheConfigurationTheInterruptedRunRecorded() throws Exception {
		Path store = temporaryDirectory.resolve("store");
		Path input = temporaryDirectory.resolve("input.nt");
		Files.writeString(input, "<urn:subject> <urn:predicate> \"literal\" .\n");
		LmdbStoreConfig original = new LmdbStoreConfig("spoc,ospc,posc");
		original.setTripleTermIndexes("spoc,cspo,posc");
		original.setInlineLiterals(false);
		AtomicInteger checks = new AtomicInteger();
		LmdbBulkLoader interrupted = LmdbBulkLoader.builder(store, original)
				.partitionCount(8)
				.workers(3)
				.cancellationSignal(() -> checks.incrementAndGet() >= 4)
				.build();
		assertThatThrownBy(() -> interrupted
				.load(List.of(new LmdbBulkLoader.PathInput(input, RDFFormat.NTRIPLES, "urn:test:base:"))))
						.isInstanceOf(CancellationException.class);

		// Only the resume question and the progress mode are left to answer; progress is about this invocation's
		// output rather than the load, so the workspace has no opinion on it.
		String answers = String.join("\n", "y", "none") + "\n";
		ByteArrayOutputStream standardOutput = new ByteArrayOutputStream();
		ByteArrayOutputStream standardError = new ByteArrayOutputStream();

		int exitCode = LmdbBulkLoad.run(new String[] { "--interactive" },
				new ByteArrayInputStream(answers.getBytes(StandardCharsets.UTF_8)),
				new PrintStream(standardOutput), new PrintStream(standardError), temporaryDirectory);

		String prompts = standardError.toString(StandardCharsets.UTF_8);
		assertThat(exitCode).as(prompts).isZero();
		Properties properties = new Properties();
		try (var inputStream = Files.newInputStream(store.resolve("store.properties"))) {
			properties.load(inputStream);
		}
		assertThat(properties)
				.as("the resumed load keeps the configuration of the run it continued")
				.containsEntry("triple-indexes", "spoc,ospc,posc")
				.containsEntry("triple-term-indexes", "spoc,cspo,posc")
				.containsEntry("inline-literals", "false");
		assertThat(prompts)
				.as("nothing the workspace already answers is asked again")
				.doesNotContain("Statement indexes [")
				.doesNotContain("RDF-star term indexes [")
				.doesNotContain("Inline literals (")
				.doesNotContain("Worker count [")
				.doesNotContain("Value partition count [")
				.doesNotContain("Compression (")
				.doesNotContain("RDF input file")
				.doesNotContain("Store directory");
	}

	/**
	 * Cancels a load the moment staging finishes, which leaves exactly the state a run interrupted after staging
	 * leaves: a workspace holding the staged inputs and no published store.
	 */
	private static void stopAfterStaging(Path store, Path input) {
		AtomicBoolean staged = new AtomicBoolean();
		LmdbBulkLoader loader = LmdbBulkLoader.builder(store, new LmdbStoreConfig())
				.progressListener(snapshot -> {
					if (snapshot.phase() == BulkLoadPhase.STAGE_INPUTS && snapshot.phaseComplete()) {
						staged.set(true);
					}
				})
				.cancellationSignal(staged::get)
				.build();
		assertThatThrownBy(() -> loader
				.load(List.of(new LmdbBulkLoader.PathInput(input, RDFFormat.NTRIPLES, "urn:test:base:"))))
						.isInstanceOf(CancellationException.class);
	}

