	@Test
	void perTierFlagsAcceptEveryLz4HighRatioLevel() throws Exception {
		for (int level = 1; level <= 17; level++) {
			Path input = temporaryDirectory.resolve("input-" + level + ".nt");
			Files.writeString(input, "<urn:subject> <urn:predicate> <urn:object> .\n");

			ByteArrayOutputStream standardOutput = new ByteArrayOutputStream();
			ByteArrayOutputStream standardError = new ByteArrayOutputStream();
			int exitCode = LmdbBulkLoad.run(new String[] {
					"--store", temporaryDirectory.resolve("store-" + level).toString(),
					"--input", input.toString(),
					"--compression-runs", "none",
					"--compression-staged", Integer.toString(level),
					"--progress", "none"
			}, new ByteArrayInputStream(new byte[0]), new PrintStream(standardOutput), new PrintStream(standardError));

			assertThat(exitCode)
					.as("level %d: %s", level, standardError.toString(StandardCharsets.UTF_8))
					.isZero();
			assertThat(standardOutput.toString(StandardCharsets.UTF_8))
					.as("level %d", level)
					.contains("stored=1")
					.contains("compression=" + (level == 9 ? "runs=none" : "runs=none,staged=" + level));
		}
	}

